'use strict';
let DATA,SCHEMA,routeVersion=0;
const view=document.querySelector('#view');
const N=new Intl.NumberFormat('vi-VN',{maximumFractionDigits:2});
const S=new Intl.NumberFormat('vi-VN',{maximumFractionDigits:6});
const money=x=>x===null||x===undefined?'—':new Intl.NumberFormat('vi-VN',{maximumFractionDigits:0}).format(x)+' ₫';
const shortMoney=x=>N.format(x/1e9)+' tỷ ₫';
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const metricNames={mae:'MAE',mse:'MSE',rmse:'RMSE',r2:'R²',mape:'MAPE'};
const colors={linear:'#407ec0',tree:'#dd9142',forest:'#8b64bf',boosting:'#ce617e',xgboost:'#168d7d'};
const fields=[['GrLivArea','Diện tích sử dụng (ft²)'],['LotArea','Diện tích đất (ft²)'],['OverallQual','Chất lượng (1–10)'],['YearBuilt','Năm xây dựng'],['BedroomAbvGr','Số phòng ngủ'],['FullBath','Phòng tắm đầy đủ']];
const MANUAL={source_id:null,fields:{},actual:'',advanced:'',verified:false,sourceNote:'Nhập tay: chưa có nhãn giá thực tế.'};
const BATCH={records:[],name:'Chưa chọn dữ liệu',currency:'VND',report:null,version:0,models:['linear','tree','forest','boosting','xgboost']};
const win=(values,maximize=false)=>{const valid=values.filter(Number.isFinite);if(!valid.length)return[];const best=maximize?Math.max(...valid):Math.min(...valid);return values.map((v,i)=>Number.isFinite(v)&&Math.abs(v-best)<=1e-10*Math.max(1,Math.abs(best))?i:-1).filter(i=>i>=0);};
const unit=k=>k==='mse'?'×10¹⁸ VND²':k==='r2'?'R²':k==='mape'?'%':'tỷ ₫';
const divisor=k=>k==='mse'?1e18:k==='r2'||k==='mape'?1:1e9;
const metricText=(k,v)=>v===null||v===undefined?'Không xác định':k==='mse'?v.toExponential(5)+' VND²':k==='r2'?S.format(v):k==='mape'?N.format(v)+'%':money(v);
const truthText=t=>t==='original_csv'?'Nhãn khớp CSV gốc':t==='user_supplied'?'Nhãn người dùng cung cấp · chưa xác minh':'Chưa có giá thực tế';
async function api(path,body){const r=await fetch('/api/'+path,body?{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}:{});let data;try{data=await r.json();}catch{throw Error('Máy chủ không trả về JSON hợp lệ. Kiểm tra dung lượng dữ liệu.');}if(!r.ok)throw Error(data.error||'Không đọc được dữ liệu.');return data;}
function heading(title,text,badge='DỮ LIỆU LINH ĐỘNG'){return `<section class="page-heading"><div><span class="eyebrow">DỰ ĐOÁN · ĐỐI CHIẾU · GIẢI THÍCH</span><h1>${esc(title)}</h1><p class="subtle">${esc(text)}</p></div><span class="badge">${badge}</span></section>`;}
function barChart(labels,values,{best=[],unit:units='tỷ ₫',divisor:div=1e9,colors:palette=null}={}){
 const W=820,H=285,L=75,R=25,T=38,B=70;const vals=values.map(v=>v/div),min=Math.min(0,...vals),max=Math.max(0,...vals),range=(max-min)||1;
 const y=v=>T+(max+range*.15-v)/(range*1.15)*(H-B-T),zero=y(0),slot=(W-L-R)/labels.length,bw=Math.min(65,slot*.52);
 let svg=`<svg viewBox="0 0 ${W} ${H}" role="img" aria-label="Biểu đồ cột, ${esc(units)}"><text x="${L}" y="15" fill="#799282" font-size="10">${esc(units)}</text>`;
 for(let j=0;j<=4;j++){const v=min+range*j/4,yy=y(v);svg+=`<line x1="${L}" x2="${W-R}" y1="${yy}" y2="${yy}" stroke="#e8eeea"/><text x="${L-9}" y="${yy+4}" text-anchor="end" fill="#859b8d" font-size="10">${N.format(v)}</text>`;}
 labels.forEach((label,i)=>{const x=L+slot*i+slot/2,yy=y(vals[i]),color=palette?.[i]||(best.includes(i)?'#16766a':'#a7beaf'),opacity=best.length&&!best.includes(i)?.48:1;svg+=`<rect x="${x-bw/2}" y="${Math.min(yy,zero)}" width="${bw}" height="${Math.max(1,Math.abs(zero-yy))}" rx="4" fill="${color}" fill-opacity="${opacity}" stroke="${best.includes(i)?color:'none'}" stroke-width="2"><title>${esc(label)}: ${S.format(values[i])}</title></rect><text x="${x}" y="${yy+(vals[i]>=0?-9:19)}" text-anchor="middle" fill="#315e49" font-size="11" font-weight="700">${units==='R²'?S.format(vals[i]):N.format(vals[i])}</text><text x="${x}" y="${H-36}" text-anchor="middle" fill="#546f5e" font-size="10">${esc(label)}</text>${best.includes(i)?`<text x="${x}" y="${H-18}" text-anchor="middle" fill="${color}" font-size="9">★ tốt nhất</text>`:''}`;});return svg+'</svg>';
}
function linesChart(series,labels,{units='tỷ ₫',div=1e9,bars=false}={}){
 const W=Math.max(900,labels.length*42),H=330,L=75,R=20,T=30,B=65,values=series.flatMap(s=>s.values.filter(Number.isFinite).map(v=>v/div));
 const min=Math.min(0,...values),max=Math.max(0,...values),range=(max-min)||1;
 const y=v=>T+(max+range*.1-v)/(range*1.1)*(H-T-B),slot=(W-L-R)/Math.max(labels.length,1),x=i=>L+slot*(i+.5),zero=y(0);
 let svg=`<svg viewBox="0 0 ${W} ${H}" role="img" aria-label="${bars?'Cột nhóm':'Các đường'} đối chiếu, ${esc(units)}"><text x="${L}" y="14" font-size="11" fill="#799282">${esc(units)}</text>`;
 for(let k=0;k<=4;k++){const v=min+range*k/4,yy=y(v);svg+=`<line x1="${L}" x2="${W-R}" y1="${yy}" y2="${yy}" stroke="#e4ece5"/><text x="${L-10}" y="${yy+4}" text-anchor="end" font-size="10" fill="#7a9483">${N.format(v)}</text>`;}
 const hasBest=series.some(s=>s.best);
 series.forEach((s,si)=>{const opacity=s.actual?1:hasBest&&!s.best?.4:1;let path='',pen=false;
  s.values.forEach((v,i)=>{if(!Number.isFinite(v)){pen=false;return;}const yy=y(v/div),xx=x(i);if(bars){const bw=Math.max(2,slot*.8/series.length);svg+=`<rect x="${xx-slot*.4+si*bw}" y="${Math.min(zero,yy)}" width="${bw-1}" height="${Math.max(1,Math.abs(zero-yy))}" fill="${s.color}" opacity="${opacity}"><title>${esc(s.name)} · ${esc(labels[i])}: ${S.format(v)}</title></rect>`;}else{path+=`${pen?'L':'M'}${xx},${yy} `;pen=true;svg+=`<circle cx="${xx}" cy="${yy}" r="${s.best?3.6:2.2}" fill="${s.color}" opacity="${opacity}"><title>${esc(s.name)} · ${esc(labels[i])}: ${S.format(v)}</title></circle>`;}});
  if(!bars)svg+=`<path d="${path}" fill="none" stroke="${s.color}" stroke-width="${s.best?4:s.actual?2.4:1.6}" opacity="${opacity}" ${s.actual?'stroke-dasharray="6 4"':''}/>`;
 });labels.forEach((l,i)=>{if(labels.length<=40||i%Math.ceil(labels.length/35)===0||i===labels.length-1)svg+=`<text x="${x(i)}" y="${H-38}" font-size="9" text-anchor="middle" fill="#6f8877">${esc(l)}</text>`;});return svg+'</svg>';
}
function legend(series){return `<div class="chart-legend">${series.map(s=>`<span style="font-weight:${s.best?800:400}"><i style="background:${s.color};height:${s.best?5:3}px"></i>${esc(s.name)}${s.best?' ★':''}</span>`).join('')}</div>`;}
function initialManual(){MANUAL.source_id=null;MANUAL.fields={...Object.fromEntries([...fields.map(x=>x[0]),'Neighborhood','GarageType'].map(k=>[k,SCHEMA.defaults[k]]))};MANUAL.actual='';MANUAL.advanced='';MANUAL.verified=false;MANUAL.sourceNote='Nhập tay: các cột không nhập dùng giá trị mặc định đã lưu. Chưa có giá bán để kiểm chứng.';}
function assignKnown(row){MANUAL.source_id=row.source_id;MANUAL.fields=Object.fromEntries([...fields.map(x=>x[0]),'Neighborhood','GarageType'].map(k=>[k,row.features[k]]));MANUAL.actual=String(row.actual_vnd);MANUAL.advanced='';MANUAL.verified=true;MANUAL.sourceNote=`ID ${row.source_id} · ${row.membership==='train'?'Đã dùng huấn luyện':'Holdout gốc'} · ${row.provenance}`;}
function referenceDataPage(){
 view.innerHTML=heading('Train / Test','Khu vực dữ liệu gốc và bộ 30 căn cố định, tách khỏi các lần nhập mới.','TẬP THAM CHIẾU GỐC')+`<div class="metrics grid-four"><div class="metric-card"><span>Train</span><strong>${DATA.split.train_size}</strong><span>Có SalePrice, đã dùng huấn luyện</span></div><div class="metric-card"><span>Holdout</span><strong>${DATA.split.test_size}</strong><span>Tái lập với random_state=42</span></div><div class="metric-card"><span>Bộ demo gốc</span><strong>30</strong><span>Chỉ là một bộ mẫu tham chiếu</span></div><div class="metric-card"><span>Kaggle test.csv</span><strong>1.459</strong><span>Không có nhãn SalePrice</span></div></div><section class="card"><h2>30 căn có nhãn giá gốc</h2><p class="subtle">Nhãn được đối chiếu với CSV giữ nguyên SHA-256. Có thể tra mọi ID có nhãn trong train.csv ở tab dự đoán, không giới hạn 30 căn này.</p><div class="button-row"><button id="data-to-compare">Dùng 30 căn để so sánh</button><button class="quiet" id="data-kaggle-test">Dùng toàn bộ test.csv không nhãn</button></div><div class="table-scroll"><table class="data-table"><thead><tr><th>ID</th><th>Diện tích (ft²)</th><th>Chất lượng</th><th>Năm xây</th><th>Khu vực</th><th>SalePrice quy đổi</th><th>Thao tác</th></tr></thead><tbody>${DATA.samples.map(r=>`<tr><th>${r.id}</th><td>${N.format(r.features.GrLivArea)}</td><td>${r.features.OverallQual}</td><td>${r.features.YearBuilt}</td><td>${esc(r.features.Neighborhood)}</td><td>${money(r.actual)}</td><td><button data-lookup="${r.id}">Tra & dự đoán</button></td></tr>`).join('')}</tbody></table></div><p id="data-message" class="subtle"></p></section><section class="card"><h2>Đánh giá khớp dữ liệu trên train/holdout gốc</h2><p class="subtle">Các chỉ số dưới đây thuộc tập cũ, không phải chỉ số của một căn hoặc file mới vừa nhập.</p><div class="table-scroll"><table><thead><tr><th>Mô hình</th><th>MSE train (VND²)</th><th>MSE holdout (VND²)</th><th>R² train</th><th>R² holdout</th><th>Chẩn đoán theo ngưỡng</th></tr></thead><tbody>${DATA.models.map(m=>`<tr><th>${esc(m.name)}</th><td>${m.metrics.train.mse.toExponential(4)}</td><td>${m.metrics.test.mse.toExponential(4)}</td><td>${S.format(m.metrics.train.r2)}</td><td>${S.format(m.metrics.test.r2)}</td><td>${esc(m.assessment.label)}</td></tr>`).join('')}</tbody></table></div><details><summary>Tiêu chí chẩn đoán và giới hạn</summary><p class="subtle">Overfit khi MAE holdout &gt; 1,35 × MAE train và R² train − holdout &gt; 0,08. Underfit khi R² hai tập &lt; 0,65 và MAE train ≥ 75% baseline train. Đây là ngưỡng minh họa. Bộ test cũ từng được dùng để chọn best_model; không gọi là đánh giá cuối trên tập chưa từng dùng trong lựa chọn.</p></details></section><section class="card"><h2>Nguồn dữ liệu và kiểm chứng</h2><p class="subtle">${esc(DATA.provenance.dataset)} ${esc(DATA.provenance.truth)}</p><p class="subtle">Đổi USD sang VND không biến dữ liệu Ames thành dữ liệu thị trường Việt Nam. Giá ngoài dữ liệu gốc chỉ được xác minh bằng nguồn nhãn riêng do người dùng cung cấp.</p><details><summary>Mã toàn vẹn dữ liệu và trọng số gốc</summary><div class="source-list">${Object.entries(DATA.integrity).map(([k,v])=>`<p><b>${esc(k)}</b><br>${v}</p>`).join('')}</div></details></section>`;
 document.querySelectorAll('[data-lookup]').forEach(b=>b.onclick=async()=>{try{assignKnown(await api('record/'+b.dataset.lookup));location.hash='#/predict/xgboost';}catch(e){document.querySelector('#data-message').textContent=e.message;}});
 document.querySelector('#data-to-compare').onclick=()=>{setBatch(DATA.samples.map(r=>({source_id:r.id})),'30 căn tham chiếu gốc','VND');location.hash='#/compare';};
 document.querySelector('#data-kaggle-test').onclick=async()=>{try{const r=await api('dataset/kaggle-test');setBatch(r.records,r.name,'USD');location.hash='#/compare';}catch(e){document.querySelector('#data-message').textContent=e.message;}};
}
function modelPage(slug='xgboost'){
 const model=DATA.models.find(m=>m.id===slug);if(!model){location.hash='#/predict/xgboost';return;}
 view.innerHTML=heading('Dự đoán bằng '+model.name,'Nhập dữ liệu mới hoặc tra căn gốc. Giá, biểu đồ và phép tính được tính lại sau mỗi lần chạy.')+`<div class="model-tabs">${DATA.models.map(m=>`<a href="#/predict/${m.id}" class="${m.id===slug?'active':''}">${esc(m.name)}</a>`).join('')}</div><div class="model-layout"><section class="card"><h2>Thông tin đầu vào</h2><div class="lookup-row"><label>Tra ID có nhãn trong train.csv<input id="lookup-id" type="number" step="1" min="1" placeholder="Ví dụ: 1000"></label><button id="lookup-button">Tra ID</button><button id="new-input" class="quiet">Nhập mới</button><button id="random-input" class="quiet">Lấy mẫu bất kỳ</button></div><p class="truth-status" id="input-source">${esc(MANUAL.sourceNote)}</p><form id="single-form"><div class="fields">${fields.map(([k,l])=>`<label>${l}<input name="${k}" type="number" step="any" value="${esc(MANUAL.fields[k])}" required ${k==='OverallQual'?'min="1" max="10"':''}></label>`).join('')}${['Neighborhood','GarageType'].map(k=>`<label>${k==='Neighborhood'?'Khu vực Ames':'Loại gara'}<select name="${k}">${k==='GarageType'?`<option value="" ${!MANUAL.fields[k]?'selected':''}>Không có / giá trị thiếu</option>`:''}${SCHEMA.categories[k].map(c=>`<option value="${esc(c)}" ${c===MANUAL.fields[k]?'selected':''}>${esc(c)}</option>`).join('')}</select></label>`).join('')}</div><label class="actual-field">Giá bán thực tế (VND) · tùy chọn<input id="actual-price" type="number" min="1" step="any" value="${esc(MANUAL.actual)}" placeholder="Để trống nếu chưa có nhãn giá"></label><p class="truth-status" id="truth-hint">${MANUAL.verified?'Giá tự tra từ đúng bản ghi gốc. Sửa đặc trưng sẽ xóa nhãn tự tra.':'Giá nhập tay là nhãn người dùng, chưa được xác minh giao dịch bên ngoài.'}</p><details><summary>Đặc trưng bổ sung · JSON tùy chọn</summary><p class="note">Nhập thêm các tên cột đúng schema để giảm số cột điền mặc định. JSON không chứa SalePrice. Đơn vị diện tích của mô hình là ft².</p><textarea class="input-json" id="advanced-json" placeholder='{"TotalBsmtSF": 1000, "GarageCars": 2}'>${esc(MANUAL.advanced)}</textarea></details><div class="control-row"><button id="run-single">Dự đoán & tính lại</button></div><p id="single-error" class="form-error"></p></form></section><section class="card"><span class="eyebrow">KẾT QUẢ SUY LUẬN THẬT</span><div id="single-result"><p class="prediction">—</p><p class="subtle">Chạy mô hình để xem kết quả cho dữ liệu hiện tại.</p></div><p class="note">${esc(model.origin)}</p></section></div><section class="card" id="live-metric-section"><h2>Biểu đồ cột và MSE của lần nhập hiện tại</h2><div id="live-metrics" class="subtle">Chỉ số tính theo đúng dữ liệu vừa nhập. Cần giá bán để tính sai số; cần nhiều mẫu có biến thiên để tính R².</div></section><section class="card" id="steps-card"><h2>Các giai đoạn tính và trọng số tham chiếu</h2><div id="trace-content" class="subtle">Chưa có lượt dự đoán.</div><div id="weights-content"></div><div id="dynamic-calculations"></div></section>`;
 const form=document.querySelector('#single-form'),version=routeVersion;let runToken=0;
 function invalidate(clearTruth=true){runToken++;if(clearTruth&&MANUAL.verified){MANUAL.actual='';MANUAL.verified=false;document.querySelector('#actual-price').value='';MANUAL.sourceNote='Đã sửa đặc trưng: đầu vào giả định dựa trên bản ghi gốc, cần nhãn giá riêng để đối chiếu.';document.querySelector('#input-source').textContent=MANUAL.sourceNote;document.querySelector('#truth-hint').textContent='Đặc trưng đã đổi: chưa có giá giao dịch thật cho cấu hình mới. Có thể nhập nhãn riêng nếu có.';}
  document.querySelector('#single-result').innerHTML='<p class="prediction">—</p><p class="subtle">Đầu vào đã thay đổi. Nhấn dự đoán để tính lại.</p>';document.querySelector('#live-metrics').textContent='Chưa chạy dữ liệu hiện tại.';document.querySelector('#trace-content').textContent='Chưa chạy dữ liệu hiện tại.';document.querySelector('#weights-content').replaceChildren();document.querySelector('#dynamic-calculations').replaceChildren();}
 form.querySelectorAll('[name]').forEach(input=>input.addEventListener('input',()=>{MANUAL.fields[input.name]=input.value;invalidate();}));
 document.querySelector('#actual-price').oninput=e=>{MANUAL.actual=e.target.value;MANUAL.verified=false;MANUAL.sourceNote=e.target.value?'Nhãn giá đang do người dùng nhập; sẽ đối chiếu lại khi khớp bản ghi gốc.':'Chưa có nhãn nhập tay; chỉ tra được giá gốc nếu bản ghi còn khớp.';document.querySelector('#input-source').textContent=MANUAL.sourceNote;invalidate(false);document.querySelector('#truth-hint').textContent='Nhãn nhập tay; hệ thống sẽ đối chiếu lại nếu khớp đúng bản ghi gốc.';};
 document.querySelector('#advanced-json').oninput=e=>{MANUAL.advanced=e.target.value;invalidate();};
 async function lookup(id){const lookupToken=++runToken;try{const r=await api('record/'+id);if(version!==routeVersion||lookupToken!==runToken)return;assignKnown(r);renderRoute();}catch(e){if(version===routeVersion)document.querySelector('#single-error').textContent=e.message;}}
 document.querySelector('#lookup-button').onclick=()=>lookup(document.querySelector('#lookup-id').value);
 document.querySelector('#random-input').onclick=()=>lookup(SCHEMA.source_ids[Math.floor(Math.random()*SCHEMA.source_ids.length)]);
 document.querySelector('#new-input').onclick=()=>{runToken++;initialManual();renderRoute();};
 form.onsubmit=async event=>{event.preventDefault();const token=++runToken,button=document.querySelector('#run-single');button.disabled=true;button.textContent='Đang tính…';document.querySelector('#single-error').textContent='';
  try{let additional=MANUAL.advanced.trim()?JSON.parse(MANUAL.advanced):{};if(!additional||Array.isArray(additional)||typeof additional!=='object')throw Error('JSON bổ sung cần là một đối tượng.');const values={...additional,...Object.fromEntries(Object.entries(MANUAL.fields).map(([k,v])=>[k,SCHEMA.numeric.includes(k)?Number(v):v]))};const record={features:values};if(MANUAL.source_id!==null)record.source_id=MANUAL.source_id;if(MANUAL.actual!=='')record.actual_vnd=Number(MANUAL.actual);
   const result=await api('evaluate',{records:[record],models:[slug],target_currency:'VND',explain:true});if(version!==routeVersion||token!==runToken)return;renderSingle(result,slug);
  }catch(e){if(version===routeVersion&&token===runToken)document.querySelector('#single-error').textContent=e.message;}
  finally{if(version===routeVersion&&token===runToken){button.disabled=false;button.textContent='Dự đoán & tính lại';}else if(version===routeVersion){button.disabled=false;button.textContent='Dự đoán & tính lại';}}
 };
}
function renderSingle(report,slug){
 const row=report.rows[0],model=report.models[0],p=model.predictions[0];
 document.querySelector('#single-result').innerHTML=`<p class="prediction">${money(p.prediction)}</p><div class="result-line"><span>Giá thực tế</span><b>${row.actual===null?'Chưa có nhãn':money(row.actual)}</b></div><div class="result-line"><span>Sai lệch dự đoán − thực tế</span><b>${money(p.error)}</b></div><div class="result-line"><span>Độ lệch phần trăm</span><b>${p.percentage_error===null?'—':N.format(p.percentage_error)+'%'}</b></div><p class="truth-status ${row.truth==='original_csv'?'verified':'supplied'}">${truthText(row.truth)}${row.membership!=='unknown'?' · '+(row.membership==='train'?'Mẫu đã dùng huấn luyện':'Holdout gốc'):''}</p>${row.warnings.length?`<div class="single-warning">${row.warnings.map(esc).join('<br>')}</div>`:''}<p class="note">Mã đánh giá: ${report.evaluation_hash.slice(0,18)}…</p>`;
 if(model.metrics){const m=model.metrics,b=report.baseline;document.querySelector('#live-metrics').innerHTML=`<div class="metrics grid-four">${['mae','mse','rmse','mape'].map(k=>`<div class="metric-card"><span>${metricNames[k]} · n=${m.n}</span><strong class="${k==='mse'?'large-mse':''}">${k==='mse'?m[k].toExponential(3):k==='mape'?N.format(m[k])+'%':shortMoney(m[k])}</strong><span>${k==='mse'?'VND²':k==='mape'?'Theo nhãn đã cung cấp':'VND quy đổi'}</span></div>`).join('')}</div><label>Chỉ số của biểu đồ cột<select id="single-metric">${Object.entries(metricNames).filter(([k])=>k!=='r2').map(([k,n])=>`<option value="${k}" ${k==='mse'?'selected':''}>${n}</option>`).join('')}</select></label><div id="single-metric-chart" class="chart"></div><p class="chart-message">${m.mse<b.mse?'MSE thấp hơn':m.mse>b.mse?'MSE cao hơn':'MSE bằng'} baseline trên chính nhãn này${model.mse_reduction_percent===null?'':': '+(model.mse_reduction_percent>=0?'giảm ':'tăng ')+N.format(Math.abs(model.mse_reduction_percent))+'%'}.</p><p class="note">Baseline dự đoán cố định ${money(report.baseline_prediction)} (giá trung bình train). “Cao/thấp” ở đây là tương đối với baseline trên cùng mẫu, không phải ngưỡng chất lượng phổ quát. Với một mẫu, MAE = RMSE = |e| và MSE = e²; R² không xác định.</p>`;
  const draw=()=>{const k=document.querySelector('#single-metric').value;document.querySelector('#single-metric-chart').innerHTML=barChart([model.name,'Baseline trung bình train'],[m[k],b[k]],{best:win([m[k],b[k]]),unit:unit(k),divisor:divisor(k)});};document.querySelector('#single-metric').onchange=draw;draw();
 }else document.querySelector('#live-metrics').innerHTML=`<p class="disabled-note">Chưa có giá bán thực tế: chưa thể tính MSE, MAE, RMSE, MAPE hoặc xác nhận dự đoán đúng. Mô hình vẫn trả giá dự đoán.</p><h3>Giá dự đoán và mức tham chiếu</h3><div class="chart">${barChart([model.name,'Trung bình train'],[p.prediction,report.baseline_prediction])}</div><p class="note">Giá trung bình train chỉ là mức tham chiếu, không thay cho giá thực tế của căn mới và không dùng để khẳng định đúng/sai.</p>`;
 document.querySelector('#live-metrics').insertAdjacentHTML('beforeend',`<div class="panel-muted"><b>Overfit / Underfit của lượt nhập này?</b><p>Không thể kết luận từ một căn. Nhận xét train/holdout gốc của ${esc(model.name)}: <b>${esc(model.original_fit_assessment.label)}</b>. <a class="inline-link" href="#/data">Xem bằng chứng và ngưỡng ở tab Train/Test →</a></p></div>`);
 renderTrace(model.trace);renderWeights(model.weights);renderDynamicCalculations(report,document.querySelector('#dynamic-calculations'));
 document.querySelector('#trace-content').insertAdjacentHTML('beforeend',`<details><summary>Diễn biến MSE / dự đoán qua các phần mô hình</summary><p class="note">${esc(model.stage_note)}</p><label>Đại lượng<select id="stage-choice"><option value="prediction">Giá dự đoán lũy kế</option>${row.actual!==null?'<option value="squared_error" selected>Sai số bình phương trên nhãn hiện tại</option>':''}</select></label><div id="stage-chart" class="chart stage-chart"></div><p id="stage-description" class="note"></p></details>`);
 const drawStages=()=>{const k=document.querySelector('#stage-choice').value,stages=model.stage_evaluation,values=stages.map(s=>s[k]);document.querySelector('#stage-chart').innerHTML=linesChart([{name:k==='prediction'?'Dự đoán lũy kế':'Sai số bình phương',values,color:colors[slug]}],stages.map(s=>'B'+s.stage),{units:k==='prediction'?'tỷ ₫':'×10¹⁸ VND²',div:k==='prediction'?1e9:1e18});const first=values[0],last=values[values.length-1];document.querySelector('#stage-description').textContent=k==='squared_error'?`MSE một mẫu từ phần đầu ${first.toExponential(5)} đến phần cuối ${last.toExponential(5)} VND²: ${last<first?'giảm':last>first?'tăng':'không đổi'}. Các phần trung gian có thể tăng/giảm; đây không phải lịch sử huấn luyện.`:'Các giá trị là phép cộng/trung bình tuần tự khi suy luận bằng trọng số đã lưu.';};document.querySelector('#stage-choice').onchange=drawStages;drawStages();
}
function renderTrace(t){
 document.querySelector('#trace-content').innerHTML=`<div class="steps"><div class="step"><div><b>Đọc đặc trưng của đúng căn đã chọn</b><p>${t.input_features} cột đầu vào; ${t.missing_values} giá trị thiếu được xử lý bởi pipeline đã fit.</p></div></div><div class="step"><div><b>Tiền xử lý bằng trọng số đã lưu</b><p>Điền thiếu và One-Hot Encoding tạo ${t.encoded_features} cột. Không fit lại trên mẫu dự đoán.</p></div></div><div class="step"><div><b>Tổng hợp đầu ra mô hình</b><p>${esc(t.formula)}</p></div></div><div class="step"><div><b>Quy đổi và đối chiếu phép tính</b><p>Dự đoán gốc × ${N.format(DATA.rate)} VND/USD; chỉ làm tròn khi hiển thị.</p></div></div></div><div class="trace-summary"><span>Khởi tạo / giá lá: ${money(t.base)}</span><span>Giá tái dựng: ${money(t.reconstructed)}</span><span>Giá predict(): ${money(t.direct_prediction)}</span><span>Kiểm tra tổng: ${t.verified?'ĐẠT':'CẦN KIỂM TRA'}</span></div><p class="note">Chênh lệch chưa làm tròn: ${N.format(t.difference)} VND; kiểm tra bằng sai số số thực, không ép dự đoán trùng nhãn thực tế.</p><details><summary>Xem toàn bộ ${t.steps.length} bước / đóng góp</summary><div class="formula">${esc(t.formula)}</div><div class="table-scroll trace-table"><table><thead><tr><th>Bước / đặc trưng</th><th>Giá trị / hiệu chỉnh (VND)</th><th>Lũy kế (VND)</th></tr></thead><tbody>${t.steps.map(r=>`<tr><td>${esc(r.stage)}</td><td>${r.amount===null?'—':money(r.amount)}</td><td>${r.cumulative===undefined?'—':money(r.cumulative)}</td></tr>`).join('')}</tbody></table></div></details>`;
}
function renderWeights(w){
 const props=Object.entries(w).filter(([k,v])=>!['items','sha256','description','importance_note','kind'].includes(k)&&typeof v!=='object');
 document.querySelector('#weights-content').innerHTML=`<details><summary>Trọng số / tham số tham chiếu thực từ mô hình</summary><p class="note">${esc(w.kind)} · ${esc(w.description)}</p><div class="weights-grid">${props.map(([k,v])=>`<span>${esc(k)}: <b>${typeof v==='number'?S.format(v):esc(v)}</b></span>`).join('')}</div><p class="note">SHA-256 mô hình: ${w.sha256}</p><p class="note">${esc(w.importance_note||'Đóng góp = đặc trưng sau tiền xử lý × hệ số VND. Hiển thị 12 đóng góp tuyệt đối lớn nhất; toàn bộ đóng góp có trong bảng các bước bên trên.')}</p><div class="table-scroll"><table class="weights-table"><thead><tr><th>Đặc trưng</th>${w.items[0]?.importance!==undefined?'<th>Importance toàn mô hình</th>':'<th>Giá trị sau mã hóa</th><th>Hệ số (VND / đơn vị)</th><th>Đóng góp (VND)</th>'}</tr></thead><tbody>${w.items.map(i=>`<tr><th>${esc(i.feature)}</th>${i.importance!==undefined?`<td>${S.format(i.importance)}</td>`:`<td>${S.format(i.input)}</td><td>${money(i.weight_vnd)}</td><td>${money(i.contribution_vnd)}</td>`}</tr>`).join('')}</tbody></table></div></details>`;
}
function renderDynamicCalculations(report,target){
 const rows=report.rows;target.innerHTML='<details open><summary>Cách tính chỉ số và kết quả đối chiếu của dữ liệu hiện tại</summary>'+report.models.map(model=>{const m=model.metrics;if(!m)return `<p class="disabled-note">${esc(model.name)}: không có nhãn để tính sai số. Không sinh chỉ số giả.</p>`;return `<h3>${esc(model.name)} · ${m.n} mẫu có nhãn / ${report.count} mẫu</h3><div class="steps"><div class="step"><div>Chạy pipeline trên dữ liệu nhập mới; quy đổi dự đoán và nhãn về cùng VND.</div></div><div class="step"><div>Với từng mẫu có nhãn: eᵢ = ŷᵢ − yᵢ; tính |eᵢ|, eᵢ² và |eᵢ|/yᵢ × 100%. Không đưa các dòng thiếu nhãn vào chỉ số.</div></div><div class="step"><div>Cộng sai số trên đúng ${m.n} dòng có nhãn và tính các chỉ số bên dưới.</div></div></div><div class="formula">MAE = ${S.format(m.sum_absolute_error)} / ${m.n} = <b>${money(m.mae)}</b><br>MSE = ${m.sse.toExponential(7)} / ${m.n} = <b>${m.mse.toExponential(7)} VND²</b><br>RMSE = √MSE = <b>${money(m.rmse)}</b><br>MAPE = ${S.format(m.sum_percentage_error)} / ${m.n} = <b>${S.format(m.mape)}%</b><br>${m.r2===null?'R²: không xác định vì n &lt; 2 hoặc các nhãn không có biến thiên.':`R² = 1 − SSE/SST = 1 − ${m.sse.toExponential(7)} / ${m.sst.toExponential(7)} = <b>${S.format(m.r2)}</b>`}</div><div class="table-scroll"><table><thead><tr><th>ID / dòng</th><th>Giá nhãn VND</th><th>Dự đoán VND</th><th>e VND</th><th>e² VND²</th><th>Nguồn nhãn</th></tr></thead><tbody>${rows.map((r,i)=>{const p=model.predictions[i];return `<tr><th>${esc(r.id)}</th><td>${money(r.actual)}</td><td>${money(p.prediction)}</td><td>${money(p.error)}</td><td>${p.squared_error===null?'—':p.squared_error.toExponential(6)}</td><td>${truthText(r.truth)}</td></tr>`;}).join('')}</tbody></table></div>`;}).join('')+'<p class="note">Đối chiếu đúng nguồn nhãn và công thức không đồng nghĩa dự đoán trùng tuyệt đối giá giao dịch hoặc đã xác minh thị trường bên ngoài.</p></details>';
 if(report.models.length>1||report.count>1)target.querySelector('details').open=false;
}
function setBatch(records,name,currency){BATCH.records=records;BATCH.name=name;BATCH.currency=currency;BATCH.report=null;BATCH.version++;}
function csvParse(text){
 const lines=[];let row=[],value='',quoted=false;text=text.replace(/^\uFEFF/,'');
 for(let i=0;i<text.length;i++){const c=text[i];if(c==='"'){if(quoted&&text[i+1]==='"'){value+='"';i++;}else if(!quoted&&value==='')quoted=true;else if(quoted)quoted=false;else throw Error('CSV có dấu ngoặc kép sai vị trí.');}else if(c===','&&!quoted){row.push(value);value='';}else if((c==='\n'||c==='\r')&&!quoted){if(c==='\r'&&text[i+1]==='\n')i++;row.push(value);if(row.some(x=>x!==''))lines.push(row);row=[];value='';}else value+=c;}
 if(quoted)throw Error('CSV chưa đóng dấu ngoặc kép.');if(value!==''||row.length){row.push(value);if(row.some(x=>x!==''))lines.push(row);}if(lines.length<2)throw Error('CSV cần có header và ít nhất một dòng dữ liệu.');
 const headers=lines.shift().map(s=>s.trim());if(new Set(headers).size!==headers.length)throw Error('CSV có cột trùng tên.');const allowed=[...SCHEMA.columns,'Id','SalePrice','ActualPriceVND','SampleID'];const unknown=headers.filter(h=>!allowed.includes(h));if(unknown.length)throw Error('Cột chưa hỗ trợ: '+unknown.join(', ')+'. Dùng tên cột House Prices; nhãn dùng SalePrice hoặc ActualPriceVND.');
 if(headers.filter(h=>SCHEMA.columns.includes(h)&&h!=='Id').length===0)throw Error('CSV không có đặc trưng nhà ngoài Id. sample_submission.csv không phải nhãn giá thật và không đủ để dự đoán.');
 if(headers.includes('SalePrice')&&headers.includes('ActualPriceVND'))throw Error('Chỉ dùng một cột nhãn: SalePrice hoặc ActualPriceVND.');
 return lines.map((cells,i)=>{if(cells.length!==headers.length)throw Error(`Dòng ${i+2}: số cột không khớp header. CSV dùng dấu phẩy, số không có dấu phân cách hàng nghìn.`);const raw=Object.fromEntries(headers.map((h,j)=>[h,cells[j]]));const features=Object.fromEntries(Object.entries(raw).filter(([k])=>SCHEMA.columns.includes(k)||k==='Id'));const record={features,id:raw.SampleID||raw.Id||String(i+1)};if(raw.ActualPriceVND?.trim())record.actual_vnd=raw.ActualPriceVND;if(raw.SalePrice?.trim())record.actual=raw.SalePrice;return record;});
}
function comparePage(){
 view.innerHTML=heading('So sánh mô hình trên dữ liệu mới','Nạp CSV của bạn hoặc chọn một bộ dữ liệu. Các dự đoán và chỉ số được tính lại từ đầu vào hiện tại.')+`<section class="card"><h2>1. Chọn dữ liệu và mô hình cần chạy</h2><div class="source-controls"><div class="upload-area"><label>Nhập CSV mới · tối đa 2.000 dòng<input type="file" id="batch-file" accept=".csv,text/csv"></label><label>Đơn vị cột SalePrice<select id="target-currency"><option value="VND" ${BATCH.currency==='VND'?'selected':''}>VND</option><option value="USD" ${BATCH.currency==='USD'?'selected':''}>USD · quy đổi về VND</option></select></label><p class="note">Cột ActualPriceVND luôn là VND. Không có cột nhãn vẫn chạy dự đoán; không thể tính sai số. Tên đặc trưng theo schema House Prices.</p><a class="inline-link" href="/examples/new_labeled_12_VND.csv">Tải CSV 12 căn khác bộ 30 để thử nhập →</a></div><div><h3>Hoặc dùng bộ đã có</h3><div class="source-buttons"><button id="use-demo" class="quiet">30 căn tham chiếu gốc</button><button id="use-kaggle" class="quiet">Kaggle test.csv · không nhãn</button></div><p class="subtle">Bộ 30 chỉ là một lựa chọn. File mới không bị giới hạn ID hoặc giá theo bộ 30. Mọi dòng trong file đều được dự đoán; biểu đồ có phân trang.</p></div></div><div class="dataset-summary"><span>Bộ hiện tại: <strong id="batch-name">${esc(BATCH.name)}</strong></span><span><b id="batch-count">${BATCH.records.length}</b> dòng đầu vào</span></div><div class="run-batch"><div class="metric-picks">${DATA.models.map(m=>`<label class="check-label"><input type="checkbox" name="batch-model" value="${m.id}" ${BATCH.models.includes(m.id)?'checked':''}>${esc(m.name)}</label>`).join('')}</div><button id="run-batch">Chạy các mô hình đã chọn</button></div><p id="batch-error" class="error"></p><div id="batch-preview" class="data-preview"></div></section><div id="batch-output">${BATCH.report?'':'<section class="card"><p class="subtle">Nạp dữ liệu rồi chạy để hiện biểu đồ và đánh giá. Không sử dụng kết quả 30 căn làm kết quả cho file mới.</p></section>'}</div>`;
 const version=routeVersion;
 function clearOutput(){BATCH.report=null;BATCH.version++;document.querySelector('#batch-output').innerHTML='<section class="card"><p class="subtle">Dữ liệu/cấu hình đã đổi. Chạy lại mô hình để cập nhật.</p></section>';}
 function refreshSource(){document.querySelector('#batch-name').textContent=BATCH.name;document.querySelector('#batch-count').textContent=BATCH.records.length;document.querySelector('#target-currency').value=BATCH.currency;clearOutput();document.querySelector('#batch-error').textContent='';document.querySelector('#batch-preview').textContent=BATCH.records.length?'Dữ liệu nạp trong phiên hiện tại. Chưa huấn luyện hoặc thay đổi trọng số.':'';}
 document.querySelector('#batch-file').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>4*1024*1024)throw Error('CSV vượt 4 MiB. Chia thành bộ nhỏ hơn.');const csvText=await file.text();if(version!==routeVersion)return;const records=csvParse(csvText);if(records.length>2000)throw Error('Tối đa 2.000 dòng mỗi lượt.');setBatch(records,file.name,document.querySelector('#target-currency').value);refreshSource();}catch(err){setBatch([],'File chưa hợp lệ',document.querySelector('#target-currency').value);refreshSource();document.querySelector('#batch-error').textContent=err.message;}};
 document.querySelector('#target-currency').onchange=e=>{BATCH.currency=e.target.value;clearOutput();};document.querySelectorAll('[name="batch-model"]').forEach(el=>el.onchange=()=>{BATCH.models=[...document.querySelectorAll('[name="batch-model"]:checked')].map(e=>e.value);clearOutput();});
 document.querySelector('#use-demo').onclick=()=>{setBatch(DATA.samples.map(r=>({source_id:r.id})),'30 căn tham chiếu gốc','VND');refreshSource();};
 document.querySelector('#use-kaggle').onclick=async()=>{try{const d=await api('dataset/kaggle-test');if(version!==routeVersion)return;setBatch(d.records,d.name,'USD');refreshSource();}catch(e){document.querySelector('#batch-error').textContent=e.message;}};
 document.querySelector('#run-batch').onclick=async()=>{const button=document.querySelector('#run-batch');const models=[...document.querySelectorAll('[name="batch-model"]:checked')].map(e=>e.value);document.querySelector('#batch-error').textContent='';if(!BATCH.records.length){document.querySelector('#batch-error').textContent='Chưa có dữ liệu. Nhập CSV hoặc chọn một bộ.';return;}if(!models.length){document.querySelector('#batch-error').textContent='Chọn ít nhất một mô hình.';return;}const token=BATCH.version;button.disabled=true;button.textContent='Đang suy luận…';try{const report=await api('evaluate',{records:BATCH.records,models,target_currency:BATCH.currency});if(version!==routeVersion||token!==BATCH.version)return;BATCH.report=report;renderBatch(report);}catch(e){if(version===routeVersion&&token===BATCH.version)document.querySelector('#batch-error').textContent=e.message;}finally{if(version===routeVersion){button.disabled=false;button.textContent='Chạy các mô hình đã chọn';}}};
 if(BATCH.report)renderBatch(BATCH.report);
}
function renderBatch(report){
 const best=report.best_by_mae||[],verified=report.rows.filter(r=>r.truth==='original_csv').length,supplied=report.rows.filter(r=>r.truth==='user_supplied').length;
 document.querySelector('#batch-output').innerHTML=`<section class="card intro"><h2>Đã chạy ${report.models.length} mô hình trên ${report.count} dòng hiện tại</h2><p class="subtle">${report.labeled_count} dòng có nhãn · ${report.unlabeled_count} dòng thiếu nhãn · ${verified} nhãn khớp CSV gốc · ${supplied} nhãn người dùng cung cấp.</p><p class="banner-proof">${best.length?'MAE thấp nhất trên đúng các dòng có nhãn: '+best.map(id=>report.models.find(m=>m.id===id).name).map(esc).join(', '):'Không có nhãn giá: chưa thể xác định mô hình tốt nhất hoặc khẳng định dự đoán đúng.'}</p><p class="note">Giá nhập CSV mới được đối chiếu với nhãn bạn cung cấp, không tự xác minh hợp đồng giao dịch bên ngoài. Dòng thiếu đặc trưng dùng mặc định và được ghi rõ trong bản xuất.</p><div class="download-controls"><button class="quiet" id="download-dynamic-csv">Tải kết quả CSV mới</button><button class="quiet" id="download-dynamic-json">Tải minh chứng JSON mới</button></div></section><section class="card"><div class="card-top"><div><span class="chart-number">01</span><h2>Giá dự đoán của các mô hình trên cùng dữ liệu</h2><p class="subtle">Mỗi mô hình một màu. Mô hình MAE tốt nhất trên bộ có nhãn được làm sáng hơn; nhãn thực tế là đường/cột đen.</p></div><span class="badge">ĐIỀU KHIỂN RIÊNG</span></div><div class="control-row"><label>Loại biểu đồ<select id="price-mode"><option value="line">5 đường theo mô hình đã chọn</option><option value="bar">Cột nhóm chung</option></select></label><label>Trang dữ liệu<select id="price-page">${Array.from({length:Math.ceil(report.count/30)},(_,i)=>`<option value="${i}">Dòng ${i*30+1}–${Math.min(report.count,(i+1)*30)}</option>`).join('')}</select></label><button id="price-apply">Cập nhật biểu đồ 1</button></div><div id="chart-one" class="chart comparison-chart"></div><div id="chart-one-legend"></div><p id="price-note" class="note"></p></section><section class="card"><div class="card-top"><div><span class="chart-number">02</span><h2>Đối chiếu từng chỉ số của dữ liệu hiện tại</h2><p class="subtle">Chỉ dùng ${report.labeled_count} dòng có nhãn trong ${report.count} dòng. Mỗi chỉ số một thang đo riêng.</p></div><span class="badge">ĐIỀU KHIỂN RIÊNG</span></div><div class="control-row"><div class="metric-picks">${Object.entries(metricNames).map(([k,n])=>`<label class="check-label"><input type="checkbox" name="metric" value="${k}" ${['mae','mse'].includes(k)?'checked':''}>${n}</label>`).join('')}</div><button id="metric-apply">Cập nhật biểu đồ 2</button></div><p id="metric-error" class="error"></p><div id="chart-two" class="small-multiples"></div></section><section class="card"><h2>Bảng chỉ số và baseline trên cùng nhãn</h2><div id="metric-summary"></div><details><summary>Overfit/underfit của file mới có kết luận được không?</summary><p class="subtle">${esc(report.fit_note)} Không dùng sai số trên một file test mới để tự kết luận quá trình học bị underfit hoặc overfit. <a class="inline-link" href="#/data">Xem cặp train/holdout gốc.</a></p></details></section><section class="card"><h2>Phép tính và nhãn đối chiếu của file này</h2><div id="batch-calculations"></div></section>`;
 const drawPrice=()=>{const start=Number(document.querySelector('#price-page').value)*30,end=Math.min(report.count,start+30),rows=report.rows.slice(start,end);const series=report.models.map(m=>({name:m.name,values:m.predictions.slice(start,end).map(p=>p.prediction),color:colors[m.id],best:best.includes(m.id)}));if(rows.some(r=>r.actual!==null))series.unshift({name:'Giá thực tế / nhãn cung cấp',values:rows.map(r=>r.actual),color:'#263d36',actual:true});document.querySelector('#chart-one').innerHTML=linesChart(series,rows.map(r=>r.id),{bars:document.querySelector('#price-mode').value==='bar'});document.querySelector('#chart-one-legend').innerHTML=legend(series);document.querySelector('#price-note').textContent=`Hiện dòng ${start+1}–${end}; đã dự đoán toàn bộ ${report.count} dòng. Chỉ số đánh giá tính trên toàn bộ ${report.labeled_count} dòng có nhãn, không chỉ trang biểu đồ này.`;};
 const drawMetrics=()=>{const picked=[...document.querySelectorAll('[name="metric"]:checked')].map(x=>x.value);if(!picked.length){document.querySelector('#metric-error').textContent='Chọn ít nhất một chỉ số.';return;}document.querySelector('#metric-error').textContent='';if(!report.labeled_count){document.querySelector('#chart-two').innerHTML='<p class="disabled-note">Thiếu nhãn giá thực tế. Không có chỉ số hoặc highlight tốt nhất để so sánh.</p>';return;}document.querySelector('#chart-two').innerHTML=picked.map(k=>{const values=report.models.map(m=>m.metrics[k]);if(values.some(v=>v===null))return `<div><h3>${metricNames[k]}</h3><p class="disabled-note">Không xác định R²: cần ít nhất hai nhãn có biến thiên.</p></div>`;const winners=win(values,k==='r2');return `<div><h3>${metricNames[k]} ${k==='r2'?'↑':'↓'}</h3><div class="chart">${barChart(report.models.map(m=>m.name),values,{best:winners,unit:unit(k),divisor:divisor(k),colors:report.models.map(m=>colors[m.id])})}</div><p class="note">Tốt nhất: ${winners.map(i=>report.models[i].name).map(esc).join(', ')}.</p></div>`;}).join('');};
 document.querySelector('#price-apply').onclick=drawPrice;document.querySelector('#metric-apply').onclick=drawMetrics;drawPrice();drawMetrics();
 document.querySelector('#metric-summary').innerHTML=report.labeled_count?`<div class="table-scroll"><table><thead><tr><th>Mô hình</th>${Object.values(metricNames).map(n=>`<th>${n}</th>`).join('')}<th>MSE so baseline</th></tr></thead><tbody>${report.models.map(m=>`<tr><th>${esc(m.name)}${best.includes(m.id)?' ★':''}</th>${Object.keys(metricNames).map(k=>`<td>${metricText(k,m.metrics[k])}</td>`).join('')}<td>${m.mse_reduction_percent===null?'Baseline bằng 0':(m.mse_reduction_percent>=0?'Giảm ':'Tăng ')+N.format(Math.abs(m.mse_reduction_percent))+'%'}</td></tr>`).join('')}</tbody></table></div><p class="note">Baseline luôn dự đoán giá trung bình train = ${money(report.baseline_prediction)}. MSE baseline trên chính nhãn file này = ${report.baseline.mse.toExponential(6)} VND². Không so sánh MSE của hai tập khác nhau để suy ra xu hướng huấn luyện.</p>`:'<p class="disabled-note">Chỉ có dự đoán, chưa có nhãn để tính bảng sai số.</p>';
 renderDynamicCalculations(report,document.querySelector('#batch-calculations'));
 document.querySelector('#download-dynamic-csv').onclick=()=>downloadDynamicCSV(report);
 document.querySelector('#download-dynamic-json').onclick=()=>downloadFile('minh_chung_du_lieu_moi.json',JSON.stringify({report,input_records:BATCH.records,target_currency:BATCH.currency,model_hashes:DATA.models.filter(m=>report.models.some(r=>r.id===m.id)).map(m=>({model:m.id,sha256:m.sha256})),truth_policy:SCHEMA.truth_policy},null,2),'application/json');
}
function downloadFile(name,text,type){const url=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function downloadDynamicCSV(report){const quote=x=>'"'+String(x??'').replace(/"/g,'""')+'"';const rows=[['model','row_id','actual_VND','predicted_VND','error_VND','squared_error_VND2','APE_percent','truth_source','membership','defaulted_columns','USD_TO_VND']];for(const m of report.models)report.rows.forEach((r,i)=>{const p=m.predictions[i];rows.push([m.name,r.id,r.actual,p.prediction,p.error,p.squared_error,p.percentage_error,r.truth,r.membership,r.defaulted_columns.join('|'),report.rate]);});downloadFile('ket_qua_du_lieu_moi_VND.csv','\uFEFF'+rows.map(r=>r.map(quote).join(',')).join('\r\n'),'text/csv;charset=utf-8');}
function renderRoute(){routeVersion++;const parts=(location.hash||'#/data').split('/'),page=parts[1]==='model'?'predict':parts[1];document.querySelectorAll('nav a').forEach(a=>a.classList.toggle('active',a.dataset.page===page));document.querySelector('#breadcrumb').textContent=page==='data'?'TRAIN / TEST':page==='compare'?'SO SÁNH DỮ LIỆU MỚI':'DỰ ĐOÁN MÔ HÌNH';if(page==='data')dataPage();else if(page==='compare')comparePage();else modelPage(parts[2]||'xgboost');}
(async()=>{try{[DATA,SCHEMA]=await Promise.all([api('audit'),api('schema')]);initialManual();document.querySelector('#status').textContent='● 5 mô hình · Nhập liệu linh động';document.querySelector('#rate-strip').textContent=`1 USD = ${N.format(DATA.rate)} VND · Tỷ giá quy đổi cố định, không phải tỷ giá trực tiếp. Dữ liệu gốc và trọng số được giữ nguyên.`;window.addEventListener('hashchange',renderRoute);renderRoute();}catch(e){document.querySelector('#status').textContent='Chưa kết nối';view.innerHTML=`<section class="card"><h1>Chưa nạp được mô hình</h1><p class="error">${esc(e.message)}</p><p>Chạy Flask: <code>python service/predict_service.py</code></p><button onclick="location.reload()">Thử lại</button></section>`;}})();

let TRAINING=null;
function dataPage(){
 referenceDataPage();
 const reference=document.createElement('details');reference.className='card';reference.innerHTML='<summary>Données tham chiếu: 30 căn minh họa, train/holdout và mã toàn vẹn</summary>'.replace('Données','Dữ liệu');
 while(view.firstChild)reference.append(view.firstChild);
 view.append(reference);
 const container=document.createElement('div');container.id='training-presentation';
 container.innerHTML=heading('Train / Test · Kết quả của nhóm','Từ dữ liệu gốc → pipeline huấn luyện → kiểm nghiệm → lựa chọn mô hình → ứng dụng dự đoán.','BÁO CÁO THỰC NGHIỆM')+`
 <section class="card intro"><div class="card-top"><div><span class="eyebrow">NGUỒN THỰC NGHIỆM</span><h2>House Prices · Ames</h2><p class="subtle">1.460 căn có nhãn SalePrice · ${SCHEMA.columns.length} cột đầu vào; Id chỉ để tra cứu · đơn vị gốc USD và ft².</p></div><a class="inline-link" href="https://github.com/tranvonghoclaptrinh/house-price-ml" target="_blank" rel="noopener">Xem repo của nhóm ↗</a></div><div class="metrics grid-four"><div class="metric-card"><span>Train · 80%</span><strong>1.168 căn</strong><span>Fit tiền xử lý và mô hình</span></div><div class="metric-card"><span>Holdout · 20%</span><strong>292 căn</strong><span>random_state = 42</span></div><div class="metric-card"><span>CV trong code nhóm</span><strong>5 folds</strong><span>Chỉ trên phần train</span></div><div class="metric-card"><span>test.csv riêng</span><strong>1.459 căn</strong><span>Không có giá để chấm điểm</span></div></div></section>
 <section class="card"><h2>Nhóm đã xây dựng mô hình như thế nào?</h2><div class="steps"><div class="step"><div><b>Tách dữ liệu và nhãn</b><p>Đọc train.csv, y = SalePrice, X = các cột còn lại, loại Id. Chia 80/20 cố định; cả 5 mô hình dùng cùng tập.</p></div></div><div class="step"><div><b>Tiền xử lý trong pipeline</b><p>Cột số điền median; cột phân loại điền “Missing” rồi One-Hot Encoding, bỏ qua nhãn chưa gặp. Tham số được fit trên train.</p></div></div><div class="step"><div><b>Huấn luyện 5 thuật toán</b><p>Linear Regression · Decision Tree (cấu hình CV) · Random Forest (cấu hình CV) · Gradient Boosting (cấu hình CV) · XGBoost (cấu hình CV).</p></div></div><div class="step"><div><b>Đánh giá và lựa chọn theo code repo</b><p>Tính MAE, RMSE, R² trên holdout và CV MAE trên train. Chọn MAE CV trên train nhỏ nhất (hòa dùng CV std); holdout chỉ dùng báo cáo. Lưu đủ 5 pipeline vào models/final và sao chép winner sang models/best_model.pkl.</p></div></div><div class="step"><div><b>Ứng dụng lại đúng pipeline đã lưu</b><p>Hai tab dự đoán/so sánh gọi cùng các file trọng số ở Flask. Nút dưới đây chỉ chạy predict và tính lại sai số; không fit lại, không đổi split hoặc ghi đè trọng số.</p></div></div></div><button id="run-training-report">Chạy kiểm nghiệm lại 5 mô hình · 292 căn</button><p id="training-status" class="subtle">Chưa chạy trong phiên này. CV và thời gian huấn luyện sẽ được ghi rõ là kết quả lịch sử từ repo.</p></section>
 <div id="training-results"></div><section class="card"><h2>Những giới hạn cần trình bày</h2><p class="warning">“Tốt nhất” là cấu hình chọn theo CV MAE trên train; holdout không tham gia lựa chọn. Không đồng nghĩa đã tối ưu toàn cục hoặc bảo đảm đúng giá mọi căn nhà.</p><ul class="subtle"><li>Winner cuối chọn theo CV train. Holdout từng được xem ở bản cũ; vẫn cần tập kiểm nghiệm mới độc lập.</li><li>Đây là dữ liệu Ames. Đổi tiền sang VND không biến mô hình thành bộ định giá nhà tại Việt Nam.</li><li>Không có SalePrice trong test.csv; sample_submission không phải giá thật.</li><li>Đã sao lưu trọng số cũ. Cả 5 pipeline cuối được script chính thức huấn luyện và lưu kèm manifest.</li><li>Chưa có khoảng dự đoán đã hiệu chuẩn hoặc dữ liệu giao dịch địa phương. Nhãn nhập tay không phải bằng chứng giao dịch được xác minh.</li></ul></section>`;
 view.prepend(container);
 document.querySelector('#run-training-report').onclick=async()=>{const version=routeVersion,b=document.querySelector('#run-training-report');b.disabled=true;document.querySelector('#training-status').textContent='Đang chạy predict trên train/holdout và đối chiếu CSV kết quả gốc…';try{TRAINING=await api('training-report',{});if(version!==routeVersion)return;renderTrainingReport();}catch(e){if(version===routeVersion)document.querySelector('#training-status').textContent=e.message;}finally{if(version===routeVersion)b.disabled=false;}};
 if(TRAINING)renderTrainingReport();
}
function renderTrainingReport(){
 const r=TRAINING,models=[...r.models].sort((a,b)=>a.metrics.test.mae-b.metrics.test.mae),best=models.find(m=>m.id===r.winner),cv=models.find(m=>m.id===r.cv_winner),t=best.metrics.test;
 document.querySelector('#training-status').textContent=`Đã chạy kiểm nghiệm: ${new Date(r.generated_at).toLocaleString('vi-VN')} · ${r.all_match_original_report?'Cả 5 mô hình khớp bảng kết quả cuối đã sinh trong sai số làm tròn.':'Có sai khác với bảng kết quả gốc; cần xem bảng đối chiếu.'} Không huấn luyện lại.`;
 document.querySelector('#training-results').innerHTML=`<section class="card intro"><span class="eyebrow">KẾT QUẢ THEO TIÊU CHÍ CỦA NHÓM</span><h2>★ ${esc(best.name)} · MAE CV train thấp nhất</h2><div class="metrics grid-four"><div class="metric-card"><span>MAE · sai số tuyệt đối trung bình</span><strong>${shortMoney(t.mae)}</strong><span>${money(t.mae)}</span></div><div class="metric-card"><span>RMSE · nhạy với sai lệch lớn</span><strong>${shortMoney(t.rmse)}</strong><span>${money(t.rmse)}</span></div><div class="metric-card"><span>R² holdout</span><strong>${S.format(t.r2)}</strong><span>Không phải % căn dự đoán đúng</span></div><div class="metric-card"><span>Sai lệch ≤ 10%</span><strong>${best.coverage['10']} / 292</strong><span>${N.format(best.coverage['10']/292*100)}% số căn holdout</span></div></div><p class="banner-proof">MSE holdout giảm ${N.format(best.baseline_mse_reduction_percent)}% so với dự đoán trung bình train trên cùng holdout. ${best.exact_count}/292 dự đoán bằng đúng giá nhãn (so số chưa làm tròn); đây không phải điều kiện cần cho mô hình hồi quy tốt.</p><div class="button-row"><button id="use-trained-best">Ứng dụng ${esc(best.name)} để dự đoán</button><button id="holdout-to-compare" class="quiet">Đưa đủ 292 căn sang So sánh</button><button id="download-training-proof" class="quiet">Tải toàn bộ minh chứng JSON</button><button id="download-holdout-csv" class="quiet">Tải đối chiếu 292 căn × 5 model</button></div></section>
 <section class="card"><h2>So sánh train và holdout · chạy lại bằng trọng số đã lưu</h2><div class="chart" id="holdout-ranking"></div><div class="table-scroll"><table><thead><tr><th>Mô hình</th><th>MAE train</th><th>MAE holdout ↓</th><th>RMSE holdout ↓</th><th>R² train</th><th>R² holdout ↑</th><th>MAPE ↓</th><th>≤5%</th><th>≤10%</th><th>≤20%</th><th>Khớp CSV gốc</th></tr></thead><tbody>${models.map(m=>`<tr class="${m.id===r.winner?'best':''}"><th>${esc(m.name)} ${m.id===r.winner?'★':''}</th><td>${money(m.metrics.train.mae)}</td><td>${money(m.metrics.test.mae)}</td><td>${money(m.metrics.test.rmse)}</td><td>${S.format(m.metrics.train.r2)}</td><td>${S.format(m.metrics.test.r2)}</td><td>${N.format(m.metrics.test.mape)}%</td>${[5,10,20].map(k=>`<td>${m.coverage[k]}/292</td>`).join('')}<td>${m.matches_original_report?'Khớp':'Sai khác'}</td></tr>`).join('')}</tbody></table></div><p class="note">Mức 5/10/20% là ngưỡng mô tả tự chọn: |ŷ − y| / y × 100. Không phải khoảng tin cậy hay bảo đảm cho căn mới.</p></section>
 <section class="card"><h2>CV và thời gian huấn luyện · kết quả nhóm đã lưu</h2><p class="subtle">Đọc results/model_results.csv; không chạy CV lại trong UI. CV tốt nhất: <b>${esc(cv.name)}</b>, MAE ${money(cv.original_report.cv_mae)}. Winner được chọn theo CV này, không theo holdout.</p><div class="table-scroll"><table><thead><tr><th>Mô hình</th><th>MAE holdout đã lưu</th><th>RMSE holdout đã lưu</th><th>R² holdout đã lưu</th><th>CV MAE · 5 folds ↓</th><th>Thời gian train (giây)</th><th>Cấu hình đã lưu</th><th>Nguồn trọng số</th></tr></thead><tbody>${models.map(m=>`<tr><th>${esc(m.name)}</th><td>${money(m.original_report.mae)}</td><td>${money(m.original_report.rmse)}</td><td>${S.format(m.original_report.r2)}</td><td>${money(m.original_report.cv_mae)} ${m.id===r.cv_winner?'★':''}</td><td>${N.format(m.original_report.training_seconds)}</td><td>${esc(JSON.stringify(m.parameters))}</td><td>${esc(m.origin)}</td></tr>`).join('')}</tbody></table></div><p class="note">Thời gian phụ thuộc máy và môi trường của lần chạy cũ. Chưa có sai số từng fold để báo cáo độ lệch chuẩn CV hoặc khẳng định chênh lệch có ý nghĩa thống kê.</p></section>
 <section class="card"><h2>Biện luận từ kết quả quan sát</h2><p class="subtle">${esc(best.name)} là lựa chọn mặc định theo CV MAE trên train, với độ lệch chuẩn dùng để phá hòa. Mô hình có MAE holdout thấp nhất trong bảng là ${esc(models[0].name)}; kết quả holdout này không được dùng để thay đổi lựa chọn đã đóng băng. Không thay trọng số chỉ để làm biểu đồ đẹp hơn.</p>${models.map(m=>`<div class="assessment"><h3>${esc(m.name)} · ${esc(m.assessment.label)}</h3><p class="subtle">MAE holdout/train = ${N.format(m.assessment.test_train_mae_ratio)}; chênh R² = ${S.format(m.assessment.r2_gap)}. ${esc(m.assessment.detail)}</p></div>`).join('')}<p class="note">Ngưỡng chẩn đoán mang tính minh họa, không thay thế learning curve/CV độc lập. Nhấn mở phần tham chiếu phía dưới để đọc ngưỡng cụ thể.</p></section>
 <section class="card"><h2>Đối chiếu từng căn với giá gốc</h2><div class="control-row"><label>Mô hình<select id="holdout-model">${models.map(m=>`<option value="${m.id}">${esc(m.name)}</option>`).join('')}</select></label><label>Trang dữ liệu<select id="holdout-page">${Array.from({length:10},(_,i)=>`<option value="${i}">${i*30+1}–${Math.min(292,(i+1)*30)}</option>`).join('')}</select></label><button id="holdout-chart-apply">Cập nhật biểu đồ</button></div><div class="chart" id="holdout-chart"></div><div id="holdout-detail"></div><div id="holdout-worst"></div></section>
 <section class="card"><h2>Minh chứng và phần còn thiếu</h2><p class="subtle">${r.repository?`Repo được đối chiếu tại commit <code>${esc(r.repository.commit)}</code>. ${r.repository.files.filter(f=>f.equivalent_content).length}/${r.repository.files.length} file của bản gốc trước sửa khớp nội dung (CSV đối chiếu giá trị, mã nguồn chuẩn hóa xuống dòng); trọng số XGBoost khớp từng byte.`:'Chưa có bản đối chiếu trực tuyến.'}</p><ul class="subtle">${r.limitations.map(s=>`<li>${esc(s)}</li>`).join('')}</ul><details><summary>File trọng số được dùng chung ở cả 3 tab</summary><div class="source-list">${models.map(m=>`<p><b>${esc(m.name)}</b> · ${esc(m.file)}<br>SHA-256: ${m.sha256}</p>`).join('')}</div></details></section>`;
 document.querySelector('#holdout-ranking').innerHTML=barChart(models.map(m=>m.name),models.map(m=>m.metrics.test.mae),{best:win(models.map(m=>m.metrics.test.mae)),colors:models.map(m=>colors[m.id])});
 const draw=()=>{const m=models.find(m=>m.id===document.querySelector('#holdout-model').value),page=+document.querySelector('#holdout-page').value,rows=m.rows.slice(page*30,page*30+30);document.querySelector('#holdout-chart').innerHTML=linesChart([{name:'SalePrice gốc',values:rows.map(x=>x.actual),color:'#263d36',actual:true},{name:m.name,values:rows.map(x=>x.prediction),color:colors[m.id]}],rows.map(x=>x.id))+legend([{name:'SalePrice gốc',color:'#263d36'},{name:m.name,color:colors[m.id]}]);const table=rs=>`<div class="table-scroll"><table><thead><tr><th>ID</th><th>Giá gốc VND</th><th>Dự đoán VND</th><th>ŷ − y</th><th>APE</th><th>Ứng dụng</th></tr></thead><tbody>${rs.map(x=>`<tr><th>${x.id}</th><td>${money(x.actual)}</td><td>${money(x.prediction)}</td><td>${money(x.error)}</td><td>${N.format(x.percentage_error)}%</td><td><button data-holdout-id="${x.id}">Mở dự đoán</button></td></tr>`).join('')}</tbody></table></div>`;document.querySelector('#holdout-detail').innerHTML=table(rows);document.querySelector('#holdout-worst').innerHTML='<h3>5 căn sai lệch tương đối lớn nhất · toàn bộ holdout</h3>'+table(m.worst);document.querySelectorAll('[data-holdout-id]').forEach(b=>b.onclick=async()=>{try{assignKnown(await api('record/'+b.dataset.holdoutId));location.hash='#/predict/'+m.id;}catch(e){document.querySelector('#training-status').textContent=e.message;}});};
 document.querySelector('#holdout-chart-apply').onclick=draw;draw();
 document.querySelector('#use-trained-best').onclick=()=>{initialManual();location.hash='#/predict/'+r.winner;};
 document.querySelector('#holdout-to-compare').onclick=()=>{setBatch(r.holdout_ids.map(i=>({source_id:i})),'292 căn holdout gốc · có SalePrice','VND');location.hash='#/compare';};
 document.querySelector('#download-training-proof').onclick=()=>downloadFile('minh_chung_train_holdout.json',JSON.stringify(r,null,2),'application/json');
 document.querySelector('#download-holdout-csv').onclick=()=>{const rows=[['model','Id','actual_VND','predicted_VND','error_VND','absolute_error_VND','APE_percent','USD_TO_VND']];for(const m of r.models)for(const row of m.rows)rows.push([m.name,row.id,row.actual,row.prediction,row.error,row.absolute_error,row.percentage_error,r.rate]);downloadFile('doi_chieu_292_can_5_model.csv','\uFEFF'+rows.map(x=>x.join(',')).join('\r\n'),'text/csv;charset=utf-8');};
}
